do -- eig 0
  local a=np.array({{0.8555441498756409,0.4142531454563141,1.106704592704773,0.11921073496341705},{-0.27817395329475403,0.4506007432937622,0.6605644822120667,-0.2905128598213196},{1.6313776969909668,0.4391338527202606,1.1075375080108643,1.380811095237732},{0.8978963494300842,0.17804870009422302,0.7019630670547485,2.5849030017852783}},np.float32)
  local w,v=np.linalg.eig(a)
  assert(w.dtype=="complex64" and v.dtype=="complex64","eig 0 dtype")
  assert(close(w.shape,{4}) and close(v.shape,{4,4}),"eig 0 shape")
  assert(eigsets_close(w:tolist(),{np.complex(3.5439746379852295,0.0),np.complex(-0.29701629281044006,0.0),np.complex(0.29656410217285156,0.0),np.complex(1.455062985420227,0.0)},0.0012),"eig 0 eigenvalues")
  local wr=np.reshape(w,insert_before_last(w.shape))
  local lhs=np.matmul(a,v); local rhs=np.multiply(v,wr)
  assert(close(lhs:tolist(),rhs:tolist(),0.011999999999999999),"eig 0 residual")
  local e=np.linalg.eigvals(a)
  assert(e.dtype=="complex64" and close(e.shape,w.shape),"eigvals 0 dtype/shape")
  assert(eigsets_close(e:tolist(),{np.complex(3.5439746379852295,0.0),np.complex(-0.29701629281044006,0.0),np.complex(0.29656410217285156,0.0),np.complex(1.455062985420227,0.0)},0.0012),"eigvals 0 values")
end
