  local sr=np.reshape(s,insert_before_last(s.shape)); local r=np.matmul(np.multiply(u,sr),vh)
  assert(close(r:tolist(),a:tolist(),3.6e-08),"svd hermitian 35 reconstruct")
  local so=np.linalg.svd(a,{compute_uv=false,hermitian=true})
  assert(close(so:tolist(),{{3.740733387393187,0.9123245582632324},{3.315386350466532,0.2261052695419598}},3e-09),"svd hermitian only 35")
end
